+// than once.
+func (c *Cursor[T]) Close() error {
+	b := c.buffer
+	b.mu.Lock()
+	defer b.mu.Unlock()
+	if c.closed {
+		return ErrUseOfClosedCursor
+	}
+	c.closed = true
+	delete(b.cursors, c)
+	if !b.closed {
+		b.pruneLocked()
+		b.wakeLocked()
+	}
+	return nil
+}
+
+func (b *Buffer[T]) updateLagLocked(c *Cursor[T]) {
+	if b.next-c.pos <= b.cfg.Capacity {
+		c.lagging = false
+		return
+	}
+	if !c.lagging {
+		c.lagging = true
+		c.lagSince = b.cfg.Clock.Now()
+	}
+}
+
+func (b *Buffer[T]) expireLocked() {
+	now := b.cfg.Clock.Now()
+	changed := false
+	for c := range b.cursors {
+		b.updateLagLocked(c)
+		if c.lagging && now.Sub(c.lagSince) >= b.cfg.GracePeriod {
+			c.err = ErrGracePeriodExceeded
+			delete(b.cursors, c)
+			changed = true
+		}
+	}
+	if changed {
+		b.pruneLocked()
+		b.wakeLocked()
+	}
+}
+
+func (b *Buffer[T]) pruneLocked() {
+	minPos := b.next
+	for c := range b.cursors {
+		if c.pos < minPos {
+			minPos = c.pos
+		}
+	}
+	drop := minPos - b.first
+	if drop == 0 {
+		return
+	}
+	if len(b.cursors) == 0 {
+		b.clearLocked()
+		b.first = b.next
+		return
+	}
+	var zero T
+	for drop > 0 && b.used > 0 {
+		b.ring[b.head] = zero
+		b.head = (b.head + 1) % len(b.ring)
+		b.used--
+		drop--
+	}
+	if drop > 0 {
+		count := int(drop)
+		for i := 0; i < count; i++ {
+			b.overflow[i] = zero
+		}
+		b.overflow = b.overflow[count:]
+	}
+	b.first = minPos
+	for b.used < len(b.ring) && len(b.overflow) > 0 {
+		b.ring[(b.head+b.used)%len(b.ring)] = b.overflow[0]
+		b.overflow[0] = zero
+		b.overflow = b.overflow[1:]
+		b.used++
+	}
+	if len(b.overflow) == 0 {
+		b.overflow = nil
+	}
+}
+
+func (b *Buffer[T]) clearLocked() {
+	var zero T
+	for i := range b.ring {
+		b.ring[i] = zero
+	}
+	for i := range b.overflow {
+		b.overflow[i] = zero
+	}
+	b.overflow = nil
+	b.used = 0
+	b.head = 0
+}
+
+func (b *Buffer[T]) wakeLocked() {
+	close(b.notify)
+	b.notify = make(chan struct{})
+}
